mapper.select:
select type as attackType, count (*) as times from situation_attack_message_history
scene_id = #{sceneId}
group by type order by times desc

select target_id as hostId, count(*) as times from situation_attack_message_history
(defense_type is null or defense_level is null or defense_level != 3) and is_history = 0
and scene_id = #{sceneId}
and type in
#{attackType}
group by target_id order by times desc

select top 1 create_time from situation_attack_message_history
scene_id = #{sceneId}
order by create_time
